      const opens = r => { const to = dz.doorTo(S, r); return to ? to.filter(p => dz.is(p, "pub") && !dz.is(p, "wc") && !/проход|коридор|шлюз|санхолл|холл/.test(dz.N(p.name))) : pub.filter(p => dz.touch(r, p) && !/проход|коридор|холл/.test(dz.N(p.name))); };
