        const pick = M.find(m => m[1] + 2.0 <= W + e && m[2] + 2.0 <= D + e) || M.find(m => m[1] + 1.2 <= W + e && m[2] + 1.2 <= D + e) || M[4];
        P("model", cU(pick[1]), (D - pick[2]) / 2, 0, { w: pick[1], h: pick[2], label: "макет " + pick[0].replace("x", "×") });
