      if (!r) { const x = +a.x || 0, y = +a.y || 0; face = face || "s"; const q = face === "e" || face === "w"; r = { x, y, w: q ? v.h : v.w, h: q ? v.w : v.h, lv: +a.lv || 0 }; }
