        for (const dx of [slack, -slack, slack / 2, -slack / 2]) { if (!dx) continue; const t = KB.setItemsIn(r, set.key, vi, face, "back").map(i => { const q = face === "e" || face === "w"; return Object.assign(i, q ? { y: r3(i.y + dx) } : { x: r3(i.x + dx) }); }); if (!hitDoor(t)) { ok = t; break; } }
